def test_get_changes_detects_new_file(initialized_repo: Path) -> None:
    (initialized_repo / "calendar" / "events.json").write_text("{}")
    changes = get_changes(repo_path=initialized_repo)
    assert len(changes) == 1
    assert changes[0].path == "calendar/events.json"
    assert changes[0].change_type == "untracked"


def test_get_changes_detects_modified_file(initialized_repo: Path) -> None:
    test_file = initialized_repo / "calendar" / ".gitkeep"
    test_file.write_text("modified")
    changes = get_changes(repo_path=initialized_repo)
    modified = [c for c in changes if c.change_type == "modified"]
    assert len(modified) == 1


