def test_get_file_at_last_commit(initialized_repo: Path) -> None:
    # Write and commit a file
    (initialized_repo / "calendar" / "events.json").write_text('{"v": 1}')
    commit_state("v1", repo_path=initialized_repo)

    # Modify the file on disk
    (initialized_repo / "calendar" / "events.json").write_text('{"v": 2}')

    # Should return the committed version
    content = get_file_at_last_commit(
        "calendar/events.json", repo_path=initialized_repo
    )
    assert content == '{"v": 1}'


